parameters.query:
/* ======== MSSQL – CPU (SQL 2008 R2 compatible) ======== */
SET NOCOUNT ON;
SET ARITHABORT ON;

DECLARE @instance_name NVARCHAR(200);
SET @instance_name = N'{{$node["Set - Params"].json["instance_name"]}}';

DECLARE @tz_offset_hours INT;
DECLARE @tz_raw NVARCHAR(50);
SET @tz_raw = N'{{$node["Set - Params"].json["tz_offset_hours"]}}';
IF @tz_raw IS NULL OR LTRIM(RTRIM(@tz_raw)) = N'' SET @tz_offset_hours = -6;
ELSE IF ISNUMERIC(@tz_raw)=1 SET @tz_offset_hours = CONVERT(INT,@tz_raw);
ELSE SET @tz_offset_hours = -6;

/* show_io_facts -> @collect_io */
DECLARE @show_io_str NVARCHAR(16) = N'{{$node["Set - Params"].json["show_io_facts"]}}';
DECLARE @collect_io BIT =
  CASE WHEN @show_io_str IS NULL OR LTRIM(RTRIM(@show_io_str))=N'' THEN 1
       WHEN LOWER(LTRIM(RTRIM(@show_io_str))) IN (N'true',N'1',N'yes',N'on') THEN 1
       ELSE 0 END;

/* usar la ventana corta (RT) para no pegarle al timeout del driver */
DECLARE @io_secs INT;
DECLARE @io_rt_raw NVARCHAR(50) = N'{{$node["Set - Params"].json["io_window_rt_sec"]}}';  -- <── 5
IF @io_rt_raw IS NULL OR LTRIM(RTRIM(@io_rt_raw))=N'' SET @io_secs = 5;
ELSE IF ISNUMERIC(@io_rt_raw)=1 SET @io_secs = CONVERT(INT,@io_rt_raw);
ELSE SET @io_secs = 5;

EXEC OpsObservability.dbo.usp_ServerMetrics
  @instance_name     = @instance_name,
  @tz_offset_hours   = @tz_offset_hours,
  @collect_io        = @collect_io,
  @io_sample_seconds = @io_secs,   -- ahora 5s
  @persist           = 1;

parameters.jsCode:
// ===== Decidir estado (con hora local) =====
const vars = $node["Set - Params"].json || {};
const threshold = Number(vars.threshold_cpu ?? 20);

const cpuRow = $node["MSSQL – CPU"]?.json || {};
const cpu = Number(cpuRow.CPU_AzurePortal_5m_pct_Avg ?? 0);

const g = $getWorkflowStaticData('global');
const lastState = g.last_state ?? 'OK';
let state = cpu >= threshold ? 'ALARM' : 'OK';
let transition = 'NONE';
const now = new Date();
const nowIso = now.toISOString();

if (state !== lastState) {
  transition = (state === 'ALARM') ? 'RAISE' : 'RECOVERY';
  g.last_state = state;
  g.last_change = nowIso;
}
g.last_seen = nowIso;

// Hora local según offset
const tz = Number(vars.tz_offset_hours ?? 0);
const localDate = new Date(now.getTime() + tz * 3600 * 1000);
const localStr = localDate.toISOString().replace("T", " ").substring(0, 19);

return [{
  json: {
    state, transition, threshold,
    cpu_portal_5m: cpu,
    instance_name: vars.instance_name || cpuRow.instance_name || "N/D",
    server: cpuRow.ServerName || vars.instance_name || "N/D",
    queryTimeUTC: nowIso,
    queryTimeLocal: localStr,
    CPU_SQL_RealTime_pct_MotorSQL: cpuRow.CPU_SQL_RealTime_pct_MotorSQL ?? 0,
    CPU_Host_RealTime_pct_VMManaged: cpuRow.CPU_Host_RealTime_pct_VMManaged ?? 0
  }
}];

// ===== Build alarm payload (local time + IO + labels humanos) =====
const P  = $node["Set - Params"]?.json || {};
const s  = $node["Function – Decidir estado"]?.json || {};
const rt = Number(P["io_window_rt_sec"] ?? 5);
const az = Number(P["io_window_azure_sec"] ?? P["io_window_avg_sec"] ?? 60);

const PROD = P.product_name || "SQL Server";
const CPU5M_LABEL = P.cpu_5m_label || "CPU (5m promedio)";
const IO_AVG_LABEL = P.io_label_avg || "1 min (promedio)";
const SHOW_IO = ("show_io_facts" in P) ? !!P.show_io_facts : true;

const s0 = $node["MSSQL – IO Snap 0"]?.json || {};
const s1 = $node["MSSQL – IO Snap 1"]?.json || {};
const s2 = $node["MSSQL – IO Snap 2"]?.json || {};
const cpuRow = $node["MSSQL – CPU"]?.json || {};

const toN = (n) => Number(n ?? 0);
const to2 = (x) => Math.round(Number(x) * 100) / 100;
const fmtPct = v => (v==null || v==="" || isNaN(v)) ? "N/D%" : `${to2(v)}%`;

// tasas
function rates(a, b, sec) {
  const dReads   = (toN(b.r_reads)         - toN(a.r_reads));
  const dWrites  = (toN(b.r_writes)        - toN(a.r_writes));
  const dReq     = dReads + dWrites;
  const dBR      = (toN(b.r_bytes_read)    - toN(a.r_bytes_read));
  const dBW      = (toN(b.r_bytes_written) - toN(a.r_bytes_written));
  return { reads: dReads/sec, writes: dWrites/sec, req_s: dReq/sec, br_s: dBR/sec, bw_s: dBW/sec };
}
const rtRates = rates(s0, s1, rt || 5);
const azRates = rates(s0, s2, az || 60);

const az_read_MB_s    = to2(azRates.br_s / 1048576);
const az_write_MB_s   = to2(azRates.bw_s / 1048576);
const az_read_MB_min  = to2(az_read_MB_s  * 60);
const az_write_MB_min = to2(az_write_MB_s * 60);

// CPU
const cpu5m    = s.cpu_portal_5m ?? cpuRow.CPU_AzurePortal_5m_pct_Avg ?? null;
const cpuSqlRT = cpuRow.CPU_SQL_RealTime_pct_MotorSQL ?? s.cpu_sql_rt ?? null;
const cpuHostRT= cpuRow.CPU_Host_RealTime_pct_VMManaged ?? s.cpu_host_rt ?? null;

// Identidad y tiempos
const instance = s.instance_name || cpuRow.instance_name || P.instance_name || "N/D";
const server   = s.server || cpuRow.ServerName || instance || "N/D";
const tzOff    = Number(P.tz_offset_hours ?? 0);

// fin de período UTC (si no viene, usa queryTimeUTC)
const bucketEndUtc = cpuRow.Azure_Bucket_End_UTC || s.bucket_end_utc || s.queryTimeUTC || null;
// local
function toLocalStr(utc, off) {
  if (!utc) return "N/D";
  const d = new Date(utc);
  const local = new Date(d.getTime() + off*3600*1000);
  return local.toISOString().replace('T',' ').substring(0,19);
}
const bucketEndLocal = toLocalStr(bucketEndUtc, tzOff);

// Sugerencias
const tips = [
  'Validar jobs/ETLs concurrentes durante la ventana de alerta (confianza: baja)',
  'Comparar CPU 5m vs RT; revisar picos de corta duración (confianza: baja)',
  'Actualizar estadísticas y revisar índices en tablas calientes (confianza: baja)'
];

// Facts principales
const facts = [
  { name: 'Servidor', value: server },
  { name: 'Hora (local)', value: s.queryTimeLocal || toLocalStr(new Date().toISOString(), tzOff) },
  { name: CPU5M_LABEL, value: fmtPct(Number(cpu5m)) },
  { name: 'CPU MotorSQL (RT)', value: fmtPct(Number(cpuSqlRT)) },
  { name: 'CPU Host (RT)', value: fmtPct(Number(cpuHostRT)) },
  { name: 'Umbral', value: `${s.threshold ?? 0}%` },
  { name: `Requests/s (RT vs ${IO_AVG_LABEL})`, value: `${to2(rtRates.req_s)} vs ${to2(azRates.req_s)}` },
  { name: 'Fin del período (hora local)', value: bucketEndLocal } // <= reemplaza “Bucket end (UTC)”
];

// IO opcional
if (SHOW_IO) {
  facts.push(
    { name: `Lectura MB/s (${IO_AVG_LABEL})`,  value: `${az_read_MB_s} MB/s (${az_read_MB_min} MB/min)` },
    { name: `Escritura MB/s (${IO_AVG_LABEL})`,value: `${az_write_MB_s} MB/s (${az_write_MB_min} MB/min)` }
  );
}

// Título
const cpu5mNum  = Number(cpu5m);
const cpu5mTitle = isNaN(cpu5mNum) ? 'N/D' : to2(cpu5mNum);
const title = `ALERTA – ${PROD} • ${instance} • CPU ${cpu5mTitle}% (umbral ${s.threshold ?? 0}%)`;

// Acciones (botones)
const actions_o365 = [];
if (P.emit_kibana_button && P.kibana_url) {
  actions_o365.push({ "@type": "OpenUri", "name": P.kibana_cta_text || "Abrir tablero (24h)", "targets": [{ "os": "default", "uri": P.kibana_url }] });
}
if (P.runbook_enabled && P.runbook_url) {
  actions_o365.push({ "@type": "OpenUri", "name": P.runbook_button_name || "Abrir runbook", "targets": [{ "os": "default", "uri": P.runbook_url }] });
}

return [{
  json: {
    instance_name: instance,
    estado: (cpu5mNum >= Number(s.threshold)) ? 'ALERTA' : 'OK',
    color: 'FF0000',
    title,
    header: `ALERTA – ${PROD}`,
    emoji: '🔴',
    facts,
    tips, tips_list: tips, suggestions: tips,
    bucket_end_utc: bucketEndUtc,
    bucket_end_local: bucketEndLocal,
    window_rt_desc: `~${rt}s`,
    window_az_desc: `~${az}s`,
    cpu_portal_5m: cpu5mNum,
    cpu_sql_rt: Number(cpuSqlRT),
    cpu_host_rt: Number(cpuHostRT),
    threshold_cpu: Number(s.threshold ?? 0),
    actions_o365
  }
}];

const rt = $node["Set - Params"].json["io_window_rt_sec"];
const az = $node["Set - Params"].json["io_window_azure_sec"];
return [{ json: { remaining_sec: Math.max(0, az - rt) } }];

parameters.query:
/* ====== Registry métricas CPU (incluye host RT) – SQL 2008 R2 ====== */
SET NOCOUNT ON;
SET ARITHABORT ON;

DECLARE @run UNIQUEIDENTIFIER = NEWID();
DECLARE @now_utc DATETIME = GETUTCDATE();
-- Normalizar a segundo (alinear buckets)
SET @now_utc = DATEADD(SECOND, DATEDIFF(SECOND, '20000101', @now_utc), '20000101');

DECLARE @instance_name NVARCHAR(200) = N'{{$json.instance_name}}';
DECLARE @id INT;

-- 1) Resolver o crear instancia (sin proc helper)
SELECT @id = instance_id
FROM dbo.monitoring_instance
WHERE instance_name = @instance_name;

IF @id IS NULL
BEGIN
    INSERT INTO dbo.monitoring_instance (instance_name, environment, region)
    VALUES (@instance_name, 'prod', 'eastus2');
    SELECT @id = SCOPE_IDENTITY();
END

/* 2) Tomar valores como texto del item
      - Preferir campos del nodo MSSQL – CPU
      - Fallback a Set – Params
      - Si no existen, usar "0"  */
DECLARE @s_cpu_rt       NVARCHAR(100) = N'{{$json["CPU_SQL_RealTime_pct_MotorSQL"] || $json.cpu_rt  || "0"}}';
DECLARE @s_cpu_1m       NVARCHAR(100) = N'{{$json["CPU_SQL_1m_pct"]               || $json.cpu_1m  || "0"}}';
DECLARE @s_cpu_5m       NVARCHAR(100) = N'{{$json["CPU_AzurePortal_5m_pct_Avg"]   || $json.cpu_5m  || "0"}}';
DECLARE @s_cpu_host_rt  NVARCHAR(100) = N'{{$json["CPU_Host_RealTime_pct_VMManaged"] || $json.cpu_host_rt || "0"}}';

-- 3) Convertir de forma segura (SQL 2008 R2) y mantener valores en tabla variable
DECLARE @vals TABLE (cpu_rt FLOAT, cpu_1m FLOAT, cpu_5m FLOAT, cpu_host_rt FLOAT);

INSERT INTO @vals(cpu_rt, cpu_1m, cpu_5m, cpu_host_rt)
SELECT
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_rt)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_rt)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_1m)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_1m)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_5m)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_5m)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_host_rt)),  '')) = 1 THEN CONVERT(FLOAT, @s_cpu_host_rt)  ELSE 0 END;

-- 4) Idempotencia: borrar si ya existen para este bucket
DELETE FROM dbo.monitoring_metric_timeseries
WHERE instance_id = @id
  AND ts_utc      = @now_utc
  AND metric_name IN ('cpu.sql.rt_pct','cpu.sql.1m_pct','cpu.sql.5m_pct','cpu.host.rt_pct');

-- 5) Insertar las métricas (SQL RT, 1m, 5m y HOST RT)
INSERT INTO dbo.monitoring_metric_timeseries (ts_utc, instance_id, metric_name,      metric_value,         dim_json, run_id)
SELECT                                           @now_utc, @id,    'cpu.sql.rt_pct',  ISNULL(v.cpu_rt, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.sql.1m_pct',  ISNULL(v.cpu_1m, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.sql.5m_pct',  ISNULL(v.cpu_5m, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.host.rt_pct', ISNULL(v.cpu_host_rt,0),NULL,    @run FROM @vals v;

-- 6) (opcional) salida de debug
SELECT
  @instance_name AS instance_name,
  @id            AS instance_id,
  @now_utc       AS ts_utc,
  v.cpu_rt,
  v.cpu_1m,
  v.cpu_5m,
  v.cpu_host_rt
FROM @vals v;

