function __teamsTextFromCard(card) {
  const lines = [];
  if (card?.title) lines.push(String(card.title), '');
  for (const sec of (card?.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ''));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push('- **' + f.name + ':** ' + f.value);
    }
    lines.push('');
  }
  return lines.join('\n').trim();
}

function __teamsTextFromAdaptive(payload) {
  const content = payload?.attachments?.[0]?.content;
  if (!content) return String(payload?.text || payload?.title || 'Notificacion');
  const lines = [];
  const walk = (items) => {
    for (const item of items || []) {
      if (item.type === 'TextBlock' && item.text) lines.push(String(item.text));
      if (item.type === 'FactSet' && item.facts) {
        for (const f of item.facts) lines.push('- **' + f.title + ':** ' + f.value);
      }
      if (item.items) walk(item.items);
      if (item.columns) for (const col of item.columns) walk(col.items);
    }
  };
  walk(content.body);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function __teamsTextFromPayload(o) {
  if (!o || typeof o !== 'object') return String(o ?? 'N/D');
  if (o.body?.text) return o.body.text;
  if (o['@type'] === 'MessageCard' || o.sections) return __teamsTextFromCard(o);
  if (o.type === 'message' && o.attachments) return __teamsTextFromAdaptive(o);
  return JSON.stringify(o, null, 2);
}

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// ===== Build Teams payload (con diagnóstico + Bloqueador/Víctima siempre) =====
const st = $node['Function – Decidir estado']?.json || {};
if (st.state !== 'ALARM') {
  // En recovery u otros estados no emitimos tarjeta de alerta
  return [];
}

const A = $node['Function – Build alarm payload']?.json || {};
const snap = $json || {};
const P  = { ...($node['Set - Params-registry']?.json||{}), ...($node['Set - Params']?.json||{}) };

const pct = v => (v==null || v==='') ? '-' : `${Number(v).toFixed(2)}%`;
const color = (Number(st.cpu_portal_5m) >= Number(st.threshold)) ? 'E81123' : '2EB886';
const secsRT = P.io_window_rt_sec || 5;
const secsAVG = P.io_window_azure_sec || P.io_window_avg_sec || 60;

// “hace X min”
function minutesAgo(tsUtc) {
  try {
    const diff = (new Date() - new Date(tsUtc)) / 60000;
    if (diff < 1) return "menos de 1 min";
    if (diff < 60) return `${Math.round(diff)} min`;
    const h = diff / 60;
    return `${h.toFixed(1)} h`;
  } catch { return ""; }
}
function toLocalStr(utc, off) {
  if (!utc) return "N/D";
  const d = new Date(utc);
  const local = new Date(d.getTime() + (Number(off||0))*3600*1000);
  return local.toISOString().replace('T',' ').substring(0,19);
}

// Nota referencial
let referentialText = "";
if (snap.referential) {
  const ago = minutesAgo(snap.ts_used);
  const tsLocal = toLocalStr(snap.ts_used, P.tz_offset_hours);
  referentialText = `⚪ **Datos referenciales** — sin actividad reciente en el último período. Usando el dato más reciente disponible (**${ago}** atrás: ${tsLocal} hora local).`;
}

// Top/esperas con explicación cuando no hay datos
const cpuTop = (snap.cpu_top_text && snap.cpu_top_text.trim())
  ? snap.cpu_top_text
  : "Sin datos: no se detectaron sesiones activas ni consultas destacadas en la ventana analizada.";
const waitTop = (snap.wait_top && snap.wait_top.trim())
  ? snap.wait_top
  : "Sin datos: no se registraron categorías de espera significativas.";

const sections = [
  {
    markdown: true,
    text: `${A.emoji || (color==='E81123' ? '🔴' : '🟢')} **${A.header || ('ALERTA – ' + (P.product_name||'SQL Server'))}**\n\nCPU 5m: **${pct(st.cpu_portal_5m)}** (umbral **${st.threshold}%**)`
  },
  { markdown: true, facts: A.facts || [] },
];

if (referentialText) sections.push({ markdown: true, text: referentialText });

// --- Diagnóstico enriquecido ---
if (snap.procesos_activos) {
  sections.push({ activityTitle: 'Por qué subió la CPU 🔎 Procesos activos (ahora)', text: snap.procesos_activos });
}
if (snap.cause_probable) {
  sections.push({ activityTitle: 'Causa probable', text: snap.cause_probable });
}
if (snap.waits_evidence) {
  sections.push({ activityTitle: 'Evidencias (waits)', text: snap.waits_evidence });
}

// Bloqueador / Víctima (fallback)
const blockerText = (snap.blocker && String(snap.blocker).trim()) ? snap.blocker : "(sin bloqueos activos)";
const victimText  = (snap.victim  && String(snap.victim ).trim()) ? snap.victim  : "(sin bloqueos activos)";
sections.push(
  { activityTitle: 'Bloqueador', text: blockerText },
  { activityTitle: 'Víctima',    text: victimText }
);

sections.push(
  { activityTitle: 'Top CPU (programa / login / base de datos)', text: cpuTop },
  { activityTitle: 'Top CPU (explicado)', text: snap.topcpu_explained || '(sin datos)' },
  { activityTitle: 'Categoría de espera principal', text: waitTop }
);

// Sugerencias + Conceptos
sections.push(
  { markdown: true, text: `💡 **Sugerencias rápidas**\n${(A.tips||[]).map(x=>`• ${x}`).join('\n')}` },
  {
    markdown: true,
    text:
      `📘 **Conceptos**\n` +
      `- **RT (~${secsRT}s):** picos instantáneos.\n` +
      `- **${P.io_label_avg || '1 min (promedio)'} (~${secsAVG}s):** actividad estable.\n` +
      `- **Hora local:** fin del período analizado.\n` +
      `- **CPU (5m promedio):** referencia de la alerta.\n` +
      (snap.referential ? `- **Datos referenciales:** sin actividad reciente, se usaron datos previos (≤15 min).` : ``)
  }
);

const card = {
  '@type': 'MessageCard',
  '@context': 'https://schema.org/extensions',
  themeColor: color,
  summary: A.title || `Alerta CPU ${st.instance_name || 'N/D'}`,
  title:   A.title || `ALERTA – ${(P.product_name||'SQL Server')} • ${(st.instance_name||'N/D')} • CPU ${pct(st.cpu_portal_5m)} (umbral ${st.threshold}%)`,
  sections,
  potentialAction: A.actions_o365 || []
};

return [{ json: { body: toAdaptiveCardBody(__teamsTextFromCard(card)) } }];

