    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}

// === Build recovery payload (RECUPERACIÓN) ===
// Genera una tarjeta verde y pone la INSTANCIA en el título.

const P = $node["Set - Params"]?.json || $node["Set - Params-registry"]?.json || {};
const inst    = P.instance_name || $json.instance_name || "N/D";
