  summary: `RECUPERADO ${inst}`,
  // 👉 aquí va la instancia:
  title: `RECUPERACIÓN – ${product} – ${inst} • CPU bajo umbral`,
  sections: [
    {
      activityTitle: 'El uso de CPU volvió a niveles normales. Se detiene la alerta continua.',
