// ===== Decidir estado (con hora local) =====
const vars = $node["Set - Params"].json || {};
const threshold = Number(vars.threshold_cpu ?? 20);

const cpuRow = $node["MSSQL – CPU"]?.json || {};
const cpu = Number(cpuRow.CPU_AzurePortal_5m_pct_Avg ?? 0);

const g = $getWorkflowStaticData('global');
const lastState = g.last_state ?? 'OK';
let state = cpu >= threshold ? 'ALARM' : 'OK';
let transition = 'NONE';
const now = new Date();
const nowIso = now.toISOString();

if (state !== lastState) {
  transition = (state === 'ALARM') ? 'RAISE' : 'RECOVERY';
  g.last_state = state;
  g.last_change = nowIso;
}
g.last_seen = nowIso;

// Hora local según offset
const tz = Number(vars.tz_offset_hours ?? 0);
const localDate = new Date(now.getTime() + tz * 3600 * 1000);
const localStr = localDate.toISOString().replace("T", " ").substring(0, 19);

return [{
  json: {
    state, transition, threshold,
    cpu_portal_5m: cpu,
    instance_name: vars.instance_name || cpuRow.instance_name || "N/D",
    server: cpuRow.ServerName || vars.instance_name || "N/D",
    queryTimeUTC: nowIso,
    queryTimeLocal: localStr,
    CPU_SQL_RealTime_pct_MotorSQL: cpuRow.CPU_SQL_RealTime_pct_MotorSQL ?? 0,
    CPU_Host_RealTime_pct_VMManaged: cpuRow.CPU_Host_RealTime_pct_VMManaged ?? 0
  }
}];

// ===== Build alarm payload (local time + IO + labels humanos) =====
const P  = $node["Set - Params"]?.json || {};
const s  = $node["Function – Decidir estado"]?.json || {};
const rt = Number(P["io_window_rt_sec"] ?? 5);
const az = Number(P["io_window_azure_sec"] ?? P["io_window_avg_sec"] ?? 60);

const PROD = P.product_name || "SQL Server";
const CPU5M_LABEL = P.cpu_5m_label || "CPU (5m promedio)";
const IO_AVG_LABEL = P.io_label_avg || "1 min (promedio)";
const SHOW_IO = ("show_io_facts" in P) ? !!P.show_io_facts : true;

const s0 = $node["MSSQL – IO Snap 0"]?.json || {};
const s1 = $node["MSSQL – IO Snap 1"]?.json || {};
const s2 = $node["MSSQL – IO Snap 2"]?.json || {};
const cpuRow = $node["MSSQL – CPU"]?.json || {};

const toN = (n) => Number(n ?? 0);
const to2 = (x) => Math.round(Number(x) * 100) / 100;
const fmtPct = v => (v==null || v==="" || isNaN(v)) ? "N/D%" : `${to2(v)}%`;

// tasas
function rates(a, b, sec) {
  const dReads   = (toN(b.r_reads)         - toN(a.r_reads));
  const dWrites  = (toN(b.r_writes)        - toN(a.r_writes));
  const dReq     = dReads + dWrites;
  const dBR      = (toN(b.r_bytes_read)    - toN(a.r_bytes_read));
  const dBW      = (toN(b.r_bytes_written) - toN(a.r_bytes_written));
  return { reads: dReads/sec, writes: dWrites/sec, req_s: dReq/sec, br_s: dBR/sec, bw_s: dBW/sec };
}
const rtRates = rates(s0, s1, rt || 5);
const azRates = rates(s0, s2, az || 60);

const az_read_MB_s    = to2(azRates.br_s / 1048576);
const az_write_MB_s   = to2(azRates.bw_s / 1048576);
const az_read_MB_min  = to2(az_read_MB_s  * 60);
const az_write_MB_min = to2(az_write_MB_s * 60);

// CPU
const cpu5m    = s.cpu_portal_5m ?? cpuRow.CPU_AzurePortal_5m_pct_Avg ?? null;
const cpuSqlRT = cpuRow.CPU_SQL_RealTime_pct_MotorSQL ?? s.cpu_sql_rt ?? null;
const cpuHostRT= cpuRow.CPU_Host_RealTime_pct_VMManaged ?? s.cpu_host_rt ?? null;

// Identidad y tiempos
const instance = s.instance_name || cpuRow.instance_name || P.instance_name || "N/D";
const server   = s.server || cpuRow.ServerName || instance || "N/D";
const tzOff    = Number(P.tz_offset_hours ?? 0);

// fin de período UTC (si no viene, usa queryTimeUTC)
const bucketEndUtc = cpuRow.Azure_Bucket_End_UTC || s.bucket_end_utc || s.queryTimeUTC || null;
// local
function toLocalStr(utc, off) {
  if (!utc) return "N/D";
  const d = new Date(utc);
  const local = new Date(d.getTime() + off*3600*1000);
  return local.toISOString().replace('T',' ').substring(0,19);
}
const bucketEndLocal = toLocalStr(bucketEndUtc, tzOff);

// Sugerencias
const tips = [
  'Validar jobs/ETLs concurrentes durante la ventana de alerta (confianza: baja)',
  'Comparar CPU 5m vs RT; revisar picos de corta duración (confianza: baja)',
  'Actualizar estadísticas y revisar índices en tablas calientes (confianza: baja)'
];

// Facts principales
const facts = [
  { name: 'Servidor', value: server },
  { name: 'Hora (local)', value: s.queryTimeLocal || toLocalStr(new Date().toISOString(), tzOff) },
  { name: CPU5M_LABEL, value: fmtPct(Number(cpu5m)) },
  { name: 'CPU MotorSQL (RT)', value: fmtPct(Number(cpuSqlRT)) },
  { name: 'CPU Host (RT)', value: fmtPct(Number(cpuHostRT)) },
  { name: 'Umbral', value: `${s.threshold ?? 0}%` },
  { name: `Requests/s (RT vs ${IO_AVG_LABEL})`, value: `${to2(rtRates.req_s)} vs ${to2(azRates.req_s)}` },
  { name: 'Fin del período (hora local)', value: bucketEndLocal } // <= reemplaza “Bucket end (UTC)”
];

// IO opcional
if (SHOW_IO) {
  facts.push(
    { name: `Lectura MB/s (${IO_AVG_LABEL})`,  value: `${az_read_MB_s} MB/s (${az_read_MB_min} MB/min)` },
    { name: `Escritura MB/s (${IO_AVG_LABEL})`,value: `${az_write_MB_s} MB/s (${az_write_MB_min} MB/min)` }
  );
}

// Título
const cpu5mNum  = Number(cpu5m);
const cpu5mTitle = isNaN(cpu5mNum) ? 'N/D' : to2(cpu5mNum);
const title = `ALERTA – ${PROD} • ${instance} • CPU ${cpu5mTitle}% (umbral ${s.threshold ?? 0}%)`;

// Acciones (botones)
const actions_o365 = [];
if (P.emit_kibana_button && P.kibana_url) {
  actions_o365.push({ "@type": "OpenUri", "name": P.kibana_cta_text || "Abrir tablero (24h)", "targets": [{ "os": "default", "uri": P.kibana_url }] });
}
if (P.runbook_enabled && P.runbook_url) {
  actions_o365.push({ "@type": "OpenUri", "name": P.runbook_button_name || "Abrir runbook", "targets": [{ "os": "default", "uri": P.runbook_url }] });
}

return [{
  json: {
    instance_name: instance,
    estado: (cpu5mNum >= Number(s.threshold)) ? 'ALERTA' : 'OK',
    color: 'FF0000',
    title,
    header: `ALERTA – ${PROD}`,
    emoji: '🔴',
    facts,
    tips, tips_list: tips, suggestions: tips,
    bucket_end_utc: bucketEndUtc,
    bucket_end_local: bucketEndLocal,
    window_rt_desc: `~${rt}s`,
    window_az_desc: `~${az}s`,
    cpu_portal_5m: cpu5mNum,
    cpu_sql_rt: Number(cpuSqlRT),
    cpu_host_rt: Number(cpuHostRT),
    threshold_cpu: Number(s.threshold ?? 0),
    actions_o365
  }
}];

const rt = $node["Set - Params"].json["io_window_rt_sec"];
const az = $node["Set - Params"].json["io_window_azure_sec"];
return [{ json: { remaining_sec: Math.max(0, az - rt) } }];

parameters.query:
/* ====== Registry métricas CPU (incluye host RT) – SQL 2008 R2 ====== */
SET NOCOUNT ON;
SET ARITHABORT ON;

DECLARE @run UNIQUEIDENTIFIER = NEWID();
DECLARE @now_utc DATETIME = GETUTCDATE();
-- Normalizar a segundo (alinear buckets)
SET @now_utc = DATEADD(SECOND, DATEDIFF(SECOND, '20000101', @now_utc), '20000101');

DECLARE @instance_name NVARCHAR(200) = N'{{$json.instance_name}}';
DECLARE @id INT;

-- 1) Resolver o crear instancia (sin proc helper)
SELECT @id = instance_id
FROM dbo.monitoring_instance
WHERE instance_name = @instance_name;

IF @id IS NULL
BEGIN
    INSERT INTO dbo.monitoring_instance (instance_name, environment, region)
    VALUES (@instance_name, 'prod', 'eastus2');
    SELECT @id = SCOPE_IDENTITY();
END

/* 2) Tomar valores como texto del item
      - Preferir campos del nodo MSSQL – CPU
      - Fallback a Set – Params
      - Si no existen, usar "0"  */
DECLARE @s_cpu_rt       NVARCHAR(100) = N'{{$json["CPU_SQL_RealTime_pct_MotorSQL"] || $json.cpu_rt  || "0"}}';
DECLARE @s_cpu_1m       NVARCHAR(100) = N'{{$json["CPU_SQL_1m_pct"]               || $json.cpu_1m  || "0"}}';
DECLARE @s_cpu_5m       NVARCHAR(100) = N'{{$json["CPU_AzurePortal_5m_pct_Avg"]   || $json.cpu_5m  || "0"}}';
DECLARE @s_cpu_host_rt  NVARCHAR(100) = N'{{$json["CPU_Host_RealTime_pct_VMManaged"] || $json.cpu_host_rt || "0"}}';

-- 3) Convertir de forma segura (SQL 2008 R2) y mantener valores en tabla variable
DECLARE @vals TABLE (cpu_rt FLOAT, cpu_1m FLOAT, cpu_5m FLOAT, cpu_host_rt FLOAT);

INSERT INTO @vals(cpu_rt, cpu_1m, cpu_5m, cpu_host_rt)
SELECT
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_rt)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_rt)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_1m)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_1m)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_5m)),       '')) = 1 THEN CONVERT(FLOAT, @s_cpu_5m)       ELSE 0 END,
  CASE WHEN ISNUMERIC(NULLIF(LTRIM(RTRIM(@s_cpu_host_rt)),  '')) = 1 THEN CONVERT(FLOAT, @s_cpu_host_rt)  ELSE 0 END;

-- 4) Idempotencia: borrar si ya existen para este bucket
DELETE FROM dbo.monitoring_metric_timeseries
WHERE instance_id = @id
  AND ts_utc      = @now_utc
  AND metric_name IN ('cpu.sql.rt_pct','cpu.sql.1m_pct','cpu.sql.5m_pct','cpu.host.rt_pct');

-- 5) Insertar las métricas (SQL RT, 1m, 5m y HOST RT)
INSERT INTO dbo.monitoring_metric_timeseries (ts_utc, instance_id, metric_name,      metric_value,         dim_json, run_id)
SELECT                                           @now_utc, @id,    'cpu.sql.rt_pct',  ISNULL(v.cpu_rt, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.sql.1m_pct',  ISNULL(v.cpu_1m, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.sql.5m_pct',  ISNULL(v.cpu_5m, 0),  NULL,     @run FROM @vals v
UNION ALL SELECT                                 @now_utc, @id,    'cpu.host.rt_pct', ISNULL(v.cpu_host_rt,0),NULL,    @run FROM @vals v;

-- 6) (opcional) salida de debug
SELECT
  @instance_name AS instance_name,
  @id            AS instance_id,
  @now_utc       AS ts_utc,
  v.cpu_rt,
  v.cpu_1m,
  v.cpu_5m,
  v.cpu_host_rt
FROM @vals v;

parameters.jsCode:
// === helpers ===
function safeItems(name){ try { return $items(name).map(i => i.json); } catch { return []; } }
function safeJSON(s){ if (!s || typeof s !== 'string') return null; try { return JSON.parse(s); } catch { return null; } }
function nice(v){ return (v ?? '').toString().trim(); }
function escSql(s){ return String(s ?? '').replace(/'/g, "''"); }
function toNumber(x, def=0){ const n = Number(x); return Number.isFinite(n) ? n : def; }
function uuidv4(){ // reemplazo de $guid()
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random()*16|0, v = c==='x' ? r : (r&0x3|0x8);
    return v.toString(16);
  });
}

function groupSum(rows, keySel, valueSel){
  const m = new Map();
  for (const r of rows){
    const k = nice(keySel(r));
    if (!k) continue;
    const add = toNumber(valueSel(r), 0);
    m.set(k, (m.get(k) || 0) + add);
  }
  return Array.from(m.entries()).map(([k,v]) => ({ key:k, value:v }));
}

function topRank(arr, topN){
  return (arr || [])
    .filter(x => x && x.key)
    .sort((a,b) => b.value - a.value)
    .slice(0, topN)
    .map((x,i) => ({ scope_key: x.key, metric_value: x.value, rank_n: i+1 }));
}

// === fuentes ===
const cpuRows = safeItems('MSSQL – CPU');  // ojo: guion EN DASH del nombre del nodo
const params  = ($items('Set - Params-registry')[0]?.json) || ($items('Set - Params')[0]?.json) || {};
const instance =
  params.instance_name
  || cpuRows[0]?.InstanceName
  || cpuRows[0]?.instance_name
  || $json.instance_name
  || 'N/D';

const ts_utc =
  cpuRows[0]?.Azure_Bucket_End_UTC
  || cpuRows[0]?.QueryTimeUTC
  || new Date().toISOString();

const run_id = cpuRows[0]?.run_id || $json.run_id || uuidv4();

const TOP_N = Number(params.topcpu_topn ?? params.topn ?? 5);

// === snapshot crudo del nodo MSSQL – CPU ===
const topActiveRaw = safeJSON(cpuRows[0]?.TopActive_Json) || [];   // sesiones activas
const topCpuRaw    = safeJSON(cpuRows[0]?.TopCPU_Json)    || [];   // queries por CPU

// === 1) TOP login/host/program por CPU (ms) desde sesiones activas ===
const topLogin = topRank(groupSum(topActiveRaw, r => r.login_name,   r => r.cpu_time), TOP_N)
  .map(x => ({ scope_type:'login',   metric_name:'cpu_ms', ...x }));

const topHost = topRank(groupSum(topActiveRaw, r => r.host_name,    r => r.cpu_time), TOP_N)
  .map(x => ({ scope_type:'host',    metric_name:'cpu_ms', ...x }));

const topProgram = topRank(groupSum(topActiveRaw, r => r.program_name, r => r.cpu_time), TOP_N)
  .map(x => ({ scope_type:'program', metric_name:'cpu_ms', ...x }));

// === 2) TOP wait_type por tiempo de espera (ms) ===
const topWaitType = topRank(groupSum(topActiveRaw, r => r.wait_type, r => r.wait_time), TOP_N)
  .map(x => ({ scope_type:'wait_type', metric_name:'wait_ms', ...x }));

// === 3) VÍCTIMAS y BLOQUEADORES por sesión ===
const victims  = [];
const blockers = [];
for (const r of topActiveRaw){
  const sid   = r.session_id;
  const blkId = r.blocking_session_id;
  if (blkId && toNumber(blkId, 0) > 0){
    victims.push ({ scope_type:'session', scope_key:String(sid),   metric_name:'blocked_by',   metric_value: toNumber(blkId,0), rank_n:null });
    blockers.push({ scope_type:'session', scope_key:String(blkId), metric_name:'blocking',     metric_value: 1,                  rank_n:null });
  }
}

// ranking de bloqueadores (quién más bloquea)
const topBlockers = topRank(groupSum(blockers, r => r.scope_key, _ => 1), TOP_N)
  .map(x => ({ scope_type:'session', metric_name:'blocking_count', ...x }));

// === 4) TOP de queries por CPU total (ms) (informativo) ===
// En tu JSON viene "QueryText" con el hash/texto
const topQueryCpu = (topCpuRaw || [])
  .map(q => ({
    scope_type:  'query',
    scope_key:   (q && q.QueryText) ? String(q.QueryText) : '',
    metric_name: 'total_cpu_ms',
    metric_value: toNumber(q?.TotalCPU_ms, 0)
  }))
  .filter(x => x.scope_key && x.metric_value > 0)
  .sort((a,b) => b.metric_value - a.metric_value)
  .slice(0, TOP_N)
  .map((x,i) => ({ ...x, rank_n: i+1 }));

// === 5) Ensamblar resultado final con contexto y escapado SQL ===
let result = [
  ...topLogin,
  ...topHost,
  ...topProgram,
  ...topWaitType,
  ...topBlockers,
  ...victims,
  ...topQueryCpu,
].map(r => ({
  ts_utc,
  run_id,
  instance_name: instance,
  scope_type: r.scope_type,
  scope_key_sql: escSql(r.scope_key),
  metric_name: r.metric_name,
  metric_value: toNumber(r.metric_value, 0),
  rank_n: (r.rank_n == null ? null : Number(r.rank_n))
}));

// === 6) Fallback de diagnóstico si no hay nada ===
if (!Array.isArray(result) || result.length === 0){
  const diag = {
    ts_utc,
    run_id,
    instance_name: instance,
    scope_type: 'diag',
    scope_key_sql: 'NO_TOPS',
    metric_name: 'no_data',
    metric_value: 0,
    reason: 'No se generaron tops en esta ventana',
    counts: {
      activeSessions: topActiveRaw.length,
      topCpuRows: topCpuRaw.length
    }
  };
  return [{ json: diag }];
}

// === salida normal (uno por fila) ===
return result.map(x => ({ json: x }));

parameters.query:
/* ======== UPSERT de TOPS (omite diag) – SQL 2008 R2 + DIAGNÓSTICO (robusto) ======== */
SET NOCOUNT ON;
SET ARITHABORT ON;

/* 0) Entradas del item actual */
DECLARE @instance_name NVARCHAR(200) = N'{{$json.instance_name}}';
DECLARE @ts_utc_str    NVARCHAR(50)  = N'{{$json.ts_utc}}';
DECLARE @scope_type    NVARCHAR(50)  = N'{{$json.scope_type}}';
DECLARE @scope_key     NVARCHAR(400) = N'{{$json.scope_key_sql}}'; -- ya viene con comillas escapadas
DECLARE @metric_name   NVARCHAR(100) = N'{{$json.metric_name}}';
DECLARE @metric_val_in NVARCHAR(100) = N'{{$json.metric_value}}';
DECLARE @rank_in       NVARCHAR(50)  = N'{{$json.rank_n}}';
DECLARE @run_in        NVARCHAR(50)  = N'{{$json.run_id}}';

/* 1) Ignorar diagnósticos */
IF (@scope_type = N'diag')
BEGIN
    SELECT N'SKIPPED_DIAG' AS action,
           @instance_name  AS instance_name,
           NULL            AS instance_id,
           @ts_utc_str     AS ts_utc_raw,
           NULL            AS ts_utc,
           @scope_type     AS scope_type,
           @scope_key      AS scope_key,
           @metric_name    AS metric_name,
           NULL            AS metric_value,
           NULL            AS rank_n,
           NULL            AS run_id;
    RETURN;
END

/* 2) Resolver instancia */
DECLARE @instance_id INT;
SELECT @instance_id = instance_id
FROM dbo.monitoring_instance WITH (NOLOCK)
WHERE instance_name = @instance_name;

IF @instance_id IS NULL
BEGIN
    INSERT INTO dbo.monitoring_instance(instance_name, environment, region)
    VALUES(@instance_name, 'prod', 'eastus2');
    SELECT @instance_id = SCOPE_IDENTITY();
END

/* 3) Normalizar y convertir entradas (sin TRY_CONVERT) */
DECLARE @ts_utc DATETIME;
SET @ts_utc = CASE WHEN @ts_utc_str IS NULL OR LTRIM(RTRIM(@ts_utc_str)) = N'' 
                   THEN NULL 
                   ELSE CAST(@ts_utc_str AS DATETIME) END;

DECLARE @metric_value FLOAT;
SET @metric_value = CASE 
    WHEN @metric_val_in IS NULL OR LTRIM(RTRIM(@metric_val_in)) = N'' THEN NULL
    WHEN ISNUMERIC(@metric_val_in) = 1 THEN CAST(@metric_val_in AS FLOAT)
    ELSE NULL
END;

DECLARE @rank_n INT;
SET @rank_n = CASE 
    WHEN @rank_in IS NULL OR LTRIM(RTRIM(@rank_in)) = N'' THEN NULL
    WHEN ISNUMERIC(@rank_in) = 1 THEN CAST(@rank_in AS INT)
    ELSE NULL
END;

DECLARE @run_id UNIQUEIDENTIFIER;
IF (@run_in IS NULL OR LTRIM(RTRIM(@run_in)) = N'' OR LEN(@run_in) NOT IN (32,36))
    SET @run_id = NEWID();
ELSE
BEGIN TRY
    SET @run_id = CAST(@run_in AS UNIQUEIDENTIFIER);
END TRY
BEGIN CATCH
    SET @run_id = NEWID();
END CATCH;

IF @rank_n IS NULL SET @rank_n = 0;
IF @metric_value IS NULL SET @metric_value = 0;

/* 4) MERGE con OUTPUT robusto */
DECLARE @merge_out TABLE([act] NVARCHAR(20));

;MERGE dbo.monitoring_top_entities AS tgt
USING (SELECT
         @ts_utc      AS ts_utc,
         @instance_id AS instance_id,
         @scope_type  AS scope_type,
         @scope_key   AS scope_key,
         @metric_name AS metric_name
      ) AS src
ON  tgt.ts_utc      = src.ts_utc
AND tgt.instance_id = src.instance_id
AND tgt.scope_type  = src.scope_type
AND tgt.scope_key   = src.scope_key
AND tgt.metric_name = src.metric_name
WHEN MATCHED THEN
  UPDATE SET
      tgt.metric_value = @metric_value,
      tgt.rank_n       = @rank_n,
      tgt.run_id       = @run_id
WHEN NOT MATCHED THEN
  INSERT (ts_utc, instance_id, scope_type, scope_key, metric_name, metric_value, rank_n, run_id)
  VALUES (@ts_utc, @instance_id, @scope_type, @scope_key, @metric_name, @metric_value, @rank_n, @run_id)
OUTPUT $ACTION INTO @merge_out([act]);

/* 5) Asegurar al menos una fila de salida */
IF NOT EXISTS (SELECT 1 FROM @merge_out)
    INSERT INTO @merge_out([act]) VALUES (N'NO_ACTION');

/* 6) Resultado diagnóstico para n8n */
SELECT 
  mo.[act]        AS action,   -- 'INSERT', 'UPDATE', 'NO_ACTION'
  @instance_name  AS instance_name,
  @instance_id    AS instance_id,
  @ts_utc_str     AS ts_utc_raw,
  @ts_utc         AS ts_utc,
  @scope_type     AS scope_type,
  @scope_key      AS scope_key,
  @metric_name    AS metric_name,
  @metric_value   AS metric_value,
  @rank_n         AS rank_n,
  @run_id         AS run_id
FROM @merge_out mo;

/* ===== Snapshot para Teams con diagnóstico + waits/bloqueo extendidos ===== */
SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;

DECLARE @instancia sysname = N'{{ 
  $json.instance_name
  || $node["Set - Params"].json["instance_name"]
  || $node["Set - Params-registry"].json["instance_name"]
}}';

DECLARE @id int = (
  SELECT TOP (1) instance_id
  FROM dbo.monitoring_instance
  WHERE instance_name = @instancia
);

IF @id IS NULL
BEGIN
  SELECT
    CAST(NULL AS nvarchar(max)) AS cpu_top_text,
    CAST(NULL AS nvarchar(max)) AS wait_top,
    CAST(NULL AS nvarchar(200)) AS blocker,
    CAST(NULL AS nvarchar(200)) AS victim,
    CAST(0    AS bit)           AS referential,
    CAST(NULL AS datetime)      AS ts_used,
    CAST(NULL AS nvarchar(200)) AS cause_probable,
    CAST(NULL AS nvarchar(max)) AS waits_evidence,
    CAST(NULL AS nvarchar(max)) AS topcpu_explained,
    CAST(NULL AS nvarchar(max)) AS procesos_activos;
  RETURN;
END

DECLARE @now_utc datetime = SYSUTCDATETIME();
DECLARE @ts_current datetime = (SELECT MAX(ts_utc) FROM dbo.monitoring_top_entities WHERE instance_id=@id);

DECLARE @has_data bit = CASE WHEN EXISTS(
  SELECT 1
  FROM dbo.monitoring_top_entities
  WHERE instance_id=@id AND ts_utc=@ts_current
    AND (
      (scope_type IN ('login','program','database') AND metric_name='cpu_pct')
      OR (scope_type IN ('wait_category','wait','wait_type') AND metric_name IN ('wait_pct','pct','percent'))
    )
) THEN 1 ELSE 0 END;

DECLARE @ts_use datetime = @ts_current;
DECLARE @referential bit = 0;

IF (@has_data = 0)
BEGIN
  SELECT TOP (1) @ts_use = ts_utc
  FROM dbo.monitoring_top_entities
  WHERE instance_id=@id
    AND ts_utc >= DATEADD(minute,-15,@now_utc)
    AND (
      (scope_type IN ('login','program','database') AND metric_name='cpu_pct')
      OR (scope_type IN ('wait_category','wait','wait_type') AND metric_name IN ('wait_pct','pct','percent'))
    )
  ORDER BY ts_utc DESC;

  IF (@ts_use IS NOT NULL)
    SET @referential = 1;
END

DECLARE @base TABLE(
  scope_type   nvarchar(64),
  scope_key    nvarchar(256),
  metric_name  nvarchar(64),
  metric_value float
);

IF (@ts_use IS NOT NULL)
BEGIN
  INSERT INTO @base (scope_type, scope_key, metric_name, metric_value)
  SELECT scope_type, scope_key, metric_name, CAST(metric_value AS float)
  FROM dbo.monitoring_top_entities
  WHERE instance_id = @id AND ts_utc = @ts_use;
END

DECLARE @cpu_top   nvarchar(max) = N'';
DECLARE @wait_top  nvarchar(200) = N'';
DECLARE @blocker   nvarchar(200) = N'';
DECLARE @victim    nvarchar(200) = N'';
DECLARE @cause     nvarchar(200) = N'';
DECLARE @waits     nvarchar(max) = N'';
DECLARE @expl      nvarchar(max) = N'';
DECLARE @procs     nvarchar(max) = N'';
DECLARE @domWait   nvarchar(200) = NULL; -- wait dominante

IF EXISTS (SELECT 1 FROM @base)
BEGIN
  ;WITH cpu_raw AS (
    SELECT TOP (10)
      scope_type AS dimension,
      scope_key  AS dimension_valor,
      metric_value AS valor
    FROM @base
    WHERE metric_name='cpu_pct' AND scope_type IN ('login','program','database')
    ORDER BY valor DESC
  )
  SELECT @cpu_top =
    STUFF((
      SELECT CHAR(10) + N'• ' + dimension + N' — ' + dimension_valor
             + N' • ' + CONVERT(nvarchar(30), CONVERT(decimal(5,2), valor)) + N'%'
      FROM cpu_raw
      FOR XML PATH(''), TYPE
    ).value('.', 'nvarchar(max)'), 1, 1, '');

  /* Waits desde snapshot si existen */
  IF EXISTS (SELECT 1 FROM @base WHERE scope_type IN ('wait_category','wait','wait_type') AND metric_name IN ('wait_pct','pct','percent'))
  BEGIN
    SELECT TOP (1)
      @domWait = scope_key,
      @wait_top = scope_key + N' • ' + CONVERT(nvarchar(30), CONVERT(decimal(5,2), metric_value)) + N' %'
    FROM @base
    WHERE scope_type IN ('wait_category','wait','wait_type') AND metric_name IN ('wait_pct','pct','percent')
    ORDER BY metric_value DESC;

    ;WITH w AS (
      SELECT TOP (3) scope_key, metric_value
      FROM @base
      WHERE scope_type IN ('wait_category','wait','wait_type') AND metric_name IN ('wait_pct','pct','percent')
      ORDER BY metric_value DESC
    )
    SELECT @waits =
      STUFF((
        SELECT CHAR(10) + N'• ' + scope_key + N' — ' 
               + CONVERT(nvarchar(30), CONVERT(decimal(5,2), metric_value)) + N'%'
        FROM w
        FOR XML PATH(''), TYPE
      ).value('.', 'nvarchar(max)'), 1, 1, '');
  END

  /* Bloqueador / víctima del snapshot (session_id como texto) */
  SELECT TOP (1) @blocker = scope_key
  FROM @base WHERE scope_type='blocker_session' AND metric_name='blocked_count'
  ORDER BY metric_value DESC;

  SELECT TOP (1) @victim = scope_key
  FROM @base WHERE scope_type='victim_session' AND metric_name='victim_wait_ms'
  ORDER BY metric_value DESC;
END

/* Fallback waits desde DMVs si snapshot no trajo */
IF (@domWait IS NULL)
BEGIN
  ;WITH w AS (
    SELECT wait_type, COUNT(*) AS cnt
    FROM sys.dm_exec_requests
    WHERE session_id <> @@SPID AND wait_type IS NOT NULL
    GROUP BY wait_type
  ),
  s AS ( SELECT SUM(cnt) AS total FROM w ),
  p AS (
    SELECT TOP (3) wait_type, CAST(100.0*cnt/(SELECT total FROM s) AS float) AS pct
    FROM w ORDER BY pct DESC
  )
  SELECT
    @domWait = (SELECT TOP 1 wait_type FROM p ORDER BY pct DESC),
    @wait_top = (SELECT TOP 1 wait_type + N' • ' + CONVERT(nvarchar(30), CONVERT(decimal(5,2), pct)) + N' %' FROM p ORDER BY pct DESC),
    @waits =
      STUFF((
        SELECT CHAR(10) + N'• ' + wait_type + N' — ' + CONVERT(nvarchar(30), CONVERT(decimal(5,2), pct)) + N'%'
        FROM p FOR XML PATH(''), TYPE
      ).value('.', 'nvarchar(max)'), 1, 1, '');
END

/* Causa probable (diccionario extendido) */
IF (@domWait IS NOT NULL)
BEGIN
  SET @cause =
    CASE
      /* IO / Log / Checkpoint */
      WHEN @domWait LIKE 'PAGEIOLATCH%' OR @domWait LIKE 'IO_%' OR @domWait LIKE 'ASYNC_IO_COMPLETION%' THEN N'I/O de datos (disco)'
      WHEN @domWait LIKE 'WRITELOG%' OR @domWait LIKE 'LOG_RATE_GOVERNOR%' OR @domWait LIKE 'LOGBUFFER%' THEN N'I/O de log / commit (limitación o presión de log)'
      WHEN @domWait LIKE 'CHECKPOINT_QUEUE%' THEN N'Checkpoint del motor (flushing de páginas)'

      /* CPU / scheduler / workers */
      WHEN @domWait LIKE 'SOS_SCHEDULER_YIELD%' THEN N'Presión de CPU / scheduler ocupado'
      WHEN @domWait LIKE 'THREADPOOL%' THEN N'Falta de workers (alto paralelismo / muchas conexiones)'

      /* Paralelismo */
      WHEN @domWait LIKE 'CXPACKET%' OR @domWait LIKE 'CXCONSUMER%' THEN N'Paralelismo (consultas repartidas)'

      /* Bloqueos / Latches */
      WHEN @domWait LIKE 'LCK_%' OR @domWait LIKE 'LATCH_%' THEN N'Bloqueos / contención en recursos'
      WHEN @domWait LIKE 'PAGELATCH%' THEN N'Contención en buffers (en memoria)'

      /* Red / cliente */
      WHEN @domWait LIKE 'ASYNC_NETWORK_IO%' THEN N'Red/cliente lento (consumo de resultados)'

      /* Memoria */
      WHEN @domWait LIKE 'RESOURCE_SEMAPHORE%' THEN N'Presión de memoria (ejecución/compilación de consultas)'

      /* HA/DR y Service Broker */
      WHEN @domWait LIKE 'HADR_%' THEN N'Replicación secundaria / AlwaysOn AG (HADR)'
      WHEN @domWait LIKE 'BROKER_TRANSMITTER%' OR @domWait LIKE 'BROKER_EVENTHANDLER%' OR @domWait LIKE 'BROKER_%' THEN N'Actividades internas de Service Broker'

      /* Backup/Restore */
      WHEN @domWait LIKE 'BACKUP%' OR @domWait LIKE 'RESTORE%' THEN N'Operaciones de backup/restore en curso'

      ELSE N'Sin patrón dominante'
    END;
END

/* Top CPU (explicado) */
DECLARE @lg nvarchar(256), @lgv float, @pr nvarchar(256), @prv float, @db nvarchar(256), @dbv float;
SELECT TOP 1 @lg=scope_key, @lgv=metric_value FROM @base WHERE metric_name='cpu_pct' AND scope_type='login'   ORDER BY metric_value DESC;
SELECT TOP 1 @pr=scope_key, @prv=metric_value FROM @base WHERE metric_name='cpu_pct' AND scope_type='program' ORDER BY metric_value DESC;
SELECT TOP 1 @db=scope_key, @dbv=metric_value FROM @base WHERE metric_name='cpu_pct' AND scope_type='database'ORDER BY metric_value DESC;

SET @expl = 
  ISNULL(N'• Login — ' + @lg + N' • ' + CONVERT(nvarchar(10), CONVERT(decimal(5,2), @lgv)) + N' %', N'') +
  CASE WHEN @pr IS NOT NULL THEN CHAR(10) + N'• Programa — ' + @pr + N' • ' + CONVERT(nvarchar(10), CONVERT(decimal(5,2), @prv)) + N' %' ELSE N'' END +
  CASE WHEN @db IS NOT NULL THEN CHAR(10) + N'• Base de datos — ' + @db + N' • ' + CONVERT(nvarchar(10), CONVERT(decimal(5,2), @dbv)) + N' %' ELSE N'' END;

/* Enriquecer bloqueador / víctima con login/program del snapshot si son numéricos */
DECLARE @blocker_id int = CASE WHEN ISNUMERIC(@blocker)=1 THEN CAST(@blocker AS int) ELSE NULL END;
DECLARE @victim_id  int = CASE WHEN ISNUMERIC(@victim )=1 THEN CAST(@victim  AS int) ELSE NULL END;

IF (@blocker_id IS NOT NULL)
BEGIN
  SELECT @blocker = CONVERT(nvarchar(10), s.session_id) + N' • ' +
                    COALESCE(s.login_name,'?') + N' • ' +
                    COALESCE(s.program_name,'?')
  FROM sys.dm_exec_sessions s
  WHERE s.session_id=@blocker_id;
END

IF (@victim_id IS NOT NULL)
BEGIN
  SELECT @victim = CONVERT(nvarchar(10), s.session_id) + N' • ' +
                   COALESCE(s.login_name,'?') + N' • ' +
                   COALESCE(s.program_name,'?')
  FROM sys.dm_exec_sessions s
  WHERE s.session_id=@victim_id;
END

/* Fallback de bloqueo actual (dm_exec_requests y dm_os_waiting_tasks) */
IF (@blocker IS NULL OR @victim IS NULL)
BEGIN
  ;WITH bx AS (
    SELECT TOP (1)
      r.session_id            AS victim_id,
      r.blocking_session_id   AS blocker_id
    FROM sys.dm_exec_requests r
    WHERE r.blocking_session_id > 0
    ORDER BY r.cpu_time DESC
  )
  SELECT
    @victim  = ISNULL(@victim,
                 (SELECT CONVERT(nvarchar(10), s.session_id) + N' • ' + COALESCE(s.login_name,'?') + N' • ' + COALESCE(s.program_name,'?')
                  FROM bx JOIN sys.dm_exec_sessions s ON s.session_id=bx.victim_id)),
    @blocker = ISNULL(@blocker,
                 (SELECT CONVERT(nvarchar(10), s.session_id) + N' • ' + COALESCE(s.login_name,'?') + N' • ' + COALESCE(s.program_name,'?')
                  FROM bx JOIN sys.dm_exec_sessions s ON s.session_id=bx.blocker_id));

  /* Segundo intento: dm_os_waiting_tasks (cadena de bloqueo) */
  IF (@blocker IS NULL OR @victim IS NULL)
  BEGIN
    ;WITH wt AS (
      SELECT TOP (1)
        w.session_id             AS victim_id,
        w.blocking_session_id    AS blocker_id
      FROM sys.dm_os_waiting_tasks w
      WHERE w.blocking_session_id > 0
      ORDER BY w.wait_duration_ms DESC
    )
    SELECT
      @victim  = ISNULL(@victim,
                   (SELECT CONVERT(nvarchar(10), s.session_id) + N' • ' + COALESCE(s.login_name,'?') + N' • ' + COALESCE(s.program_name,'?')
                    FROM wt JOIN sys.dm_exec_sessions s ON s.session_id=wt.victim_id)),
      @blocker = ISNULL(@blocker,
                   (SELECT CONVERT(nvarchar(10), s.session_id) + N' • ' + COALESCE(s.login_name,'?') + N' • ' + COALESCE(s.program_name,'?')
                    FROM wt JOIN sys.dm_exec_sessions s ON s.session_id=wt.blocker_id));
  END
END

/* Procesos activos (ahora) */
;WITH r AS (
  SELECT TOP (8)
    r.session_id AS Ses,
    DB_NAME(r.database_id) AS DBName,
    r.wait_type,
    r.cpu_time,
    r.total_elapsed_time,
    r.blocking_session_id,
    SUBSTRING(t.text,
      (r.statement_start_offset/2)+1,
      ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1
    ) AS stmt
  FROM sys.dm_exec_requests AS r
  CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) AS t
  WHERE r.session_id <> @@SPID
  ORDER BY r.cpu_time DESC
)
SELECT @procs =
  STUFF((
    SELECT CHAR(10) + N'• ' + COALESCE(NULLIF(LTRIM(RTRIM(stmt)),''),'(N/D)')
           + N' — Ses:' + CONVERT(varchar(10), Ses)
           + CASE WHEN blocking_session_id IS NOT NULL AND blocking_session_id > 0 THEN N' • BlockedBy:' + CONVERT(varchar(10), blocking_session_id) ELSE N'' END
           + N' • Wait:' + COALESCE(wait_type,'N/A')
           + N' • CPU:' + CONVERT(varchar(20), cpu_time) + N'ms'
           + N' • DB:'  + COALESCE(DBName,'N/A')
    FROM r
    FOR XML PATH(''), TYPE
  ).value('.', 'nvarchar(max)'), 1, 1, '');

IF (@procs IS NULL OR @procs = N'')
  SET @procs = N'(sin procesos activos)';

SELECT 
  NULLIF(@cpu_top,'') AS cpu_top_text,
  NULLIF(@wait_top,'') AS wait_top,
  NULLIF(@blocker,'')  AS blocker,
  NULLIF(@victim,'')   AS victim,
  @referential          AS referential,
  @ts_use               AS ts_used,
  NULLIF(@cause,'')     AS cause_probable,
  NULLIF(@waits,'')     AS waits_evidence,
  NULLIF(@expl,'')      AS topcpu_explained,
  NULLIF(@procs,'')     AS procesos_activos;

SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

